create table if not exists public.ticket_integrations (id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,provider text not null,display_name text not null,enabled boolean not null default true,status text not null default 'configured',config jsonb not null default '{}'::jsonb,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,provider));
create table if not exists public.incident_tickets (id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,incident_id uuid not null references public.incidents(id) on delete cascade,integration_id uuid not null references public.ticket_integrations(id) on delete restrict,provider text not null,external_ticket_id text,external_url text,status text not null default 'pending',assignee text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.ticket_integrations enable row level security;alter table public.incident_tickets enable row level security;
drop policy if exists ticket_integrations_member on public.ticket_integrations;create policy ticket_integrations_member on public.ticket_integrations for all to authenticated using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id) and (created_by is null or created_by=auth.uid()));
drop policy if exists incident_tickets_member on public.incident_tickets;create policy incident_tickets_member on public.incident_tickets for all to authenticated using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id) and (created_by is null or created_by=auth.uid()));
grant select,insert,update,delete on public.ticket_integrations,public.incident_tickets to authenticated;
create index if not exists incident_tickets_incident_idx on public.incident_tickets(incident_id,created_at desc);create index if not exists ticket_integrations_workspace_idx on public.ticket_integrations(workspace_id,provider);